.company-video__text { margin: 0; color: var(--cms-color-text-muted); }
.company-video__transcript { border-top: 1px solid var(--cms-color-border); padding-top: 0.75rem; }
.company-video__summary { cursor: pointer; color: var(--cms-color-accent-strong); font-weight: 600; }
.company-video__summary:hover { text-decoration: underline; }
.company-video__summary:focus-visible { text-decoration: underline; outline: 2px solid var(--cms-color-accent); outline-offset: 2px; }
.company-video__transcript-body { margin-top: 0.75rem; color: var(--cms-color-text-muted); }
@media (min-width: 48rem) { .company-video { gap: 1.5rem; } .company-video__text { font-size: 1.125rem; text-align: center; } .company-video__title { text-align: center; } }"}

